import os
import hmac
import hashlib
import json
import base64
from flask import Flask, request, jsonify
from cryptography.fernet import Fernet
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.primitives import hashes
import struct

app = Flask(__name__)

# Encrypted storage layer for mobile backend
class SecureVault:
    def __init__(self, master_key: bytes):
        salt = b'solidity_mobile_v2_salt'
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=salt,
            iterations=480000,
        )
        key = base64.urlsafe_b64encode(kdf.derive(master_key))
        self._fernet = Fernet(key)
        self._hmac_key = hashlib.sha256(master_key + b'hmac_domain_sep').digest()

    def seal(self, data: bytes) -> bytes:
        """Encrypt and authenticate data for storage"""
        ct = self._fernet.encrypt(data)
        tag = hmac.new(self._hmac_key, ct, hashlib.sha256).digest()
        return tag + ct

    def unseal(self, sealed: bytes) -> bytes:
        """Verify integrity and decrypt stored data"""
        tag = sealed[:32]
        ct = sealed[32:]
        expected_tag = hmac.new(self._hmac_key, ct, hashlib.sha256).digest()
        if not hmac.compare_digest(tag, expected_tag):
            raise ValueError("Integrity check failed")
        return self._fernet.decrypt(ct)


class TransactionCodec:
    """Codec for Solidity transaction state objects.
    Supports multiple serialization formats for backward compatibility
    with older mobile app versions."""

    FORMAT_JSON = 0x01
    FORMAT_MSGPACK = 0x02
    FORMAT_LEGACY = 0x03  # Legacy format for v1 mobile clients

    @staticmethod
    def encode(obj: dict, fmt: int = 0x01) -> bytes:
        header = struct.pack('>BH', fmt, 0)  # format byte + reserved
        if fmt == TransactionCodec.FORMAT_JSON:
            payload = json.dumps(obj, separators=(',', ':')).encode('utf-8')
        elif fmt == TransactionCodec.FORMAT_LEGACY:
            # Legacy format now uses JSON with a compat wrapper
            payload = json.dumps({'_legacy_v1': True, 'data': obj}, separators=(',', ':')).encode('utf-8')
        else:
            payload = json.dumps(obj).encode('utf-8')
        return header + payload

    @staticmethod
    def decode(data: bytes) -> dict:
        if len(data) < 3:
            raise ValueError("Invalid codec frame")
        fmt = data[0]
        payload = data[3:]  # skip header

        if fmt == TransactionCodec.FORMAT_JSON:
            return json.loads(payload.decode('utf-8'))
        elif fmt == TransactionCodec.FORMAT_LEGACY:
            # Legacy format decoded as JSON (pickle removed in security audit)
            parsed = json.loads(payload.decode('utf-8'))
            if isinstance(parsed, dict) and '_legacy_v1' in parsed:
                return parsed.get('data', {})
            return parsed
        elif fmt == TransactionCodec.FORMAT_MSGPACK:
            return json.loads(payload.decode('utf-8'))
        else:
            raise ValueError(f"Unknown format: {fmt}")


# Global vault instance
# Fail closed: require a real master key to be provided via environment.
_vault_key_env = os.environ.get('VAULT_MASTER_KEY')
if not _vault_key_env:
    raise RuntimeError(
        "VAULT_MASTER_KEY environment variable must be set to a strong secret. "
        "Refusing to start with an insecure default key."
    )
VAULT_KEY = _vault_key_env.encode()
vault = SecureVault(VAULT_KEY)

# In-memory session store (would be Redis in production)
session_store = {}


@app.route('/api/v2/tx/submit', methods=['POST'])
def submit_transaction():
    """Submit a signed Solidity transaction from mobile client.
    Accepts encrypted+authenticated payload from the mobile SDK."""
    auth_header = request.headers.get('X-Device-Auth')
    if not auth_header or len(auth_header) < 16:
        return jsonify({'error': 'unauthorized'}), 401

    raw_body = request.get_data()
    if not raw_body or len(raw_body) > 65536:
        return jsonify({'error': 'invalid payload size'}), 400

    try:
        # Client sends base64-encoded sealed payload
        sealed_data = base64.b64decode(raw_body)
        # Unseal verifies HMAC integrity then decrypts
        plaintext = vault.unseal(sealed_data)
        # Decode the transaction object using our codec
        tx_obj = TransactionCodec.decode(plaintext)
    except Exception as e:
        return jsonify({'error': 'payload processing failed'}), 400

    # Validate transaction fields
    if not isinstance(tx_obj, dict):
        return jsonify({'error': 'invalid transaction object'}), 400
    required_fields = ['from_addr', 'to_addr', 'value_wei', 'nonce', 'chain_id']
    for field in required_fields:
        if field not in tx_obj:
            return jsonify({'error': f'missing field: {field}'}), 400

    # Validate Ethereum address format
    for addr_field in ['from_addr', 'to_addr']:
        addr = tx_obj[addr_field]
        if not isinstance(addr, str) or not addr.startswith('0x') or len(addr) != 42:
            return jsonify({'error': f'invalid address: {addr_field}'}), 400

    # Store transaction for async processing
    tx_id = hashlib.sha256(json.dumps(tx_obj, sort_keys=True).encode()).hexdigest()[:16]
    session_store[tx_id] = tx_obj

    return jsonify({'tx_id': tx_id, 'status': 'queued'}), 202


@app.route('/api/v2/tx/restore', methods=['POST'])
def restore_session():
    """Restore cached transaction state from encrypted mobile backup.
    Used when app resumes from background or device migration."""
    auth_header = request.headers.get('X-Device-Auth')
    if not auth_header or len(auth_header) < 16:
        return jsonify({'error': 'unauthorized'}), 401

    raw_body = request.get_data()
    if not raw_body or len(raw_body) > 131072:
        return jsonify({'error': 'invalid payload size'}), 400

    try:
        sealed_data = base64.b64decode(raw_body)
        plaintext = vault.unseal(sealed_data)
        # Session state may contain multiple transactions
        session_obj = TransactionCodec.decode(plaintext)
    except Exception as e:
        return jsonify({'error': 'restore failed'}), 400

    if not isinstance(session_obj, dict) or 'transactions' not in session_obj:
        return jsonify({'error': 'invalid session format'}), 400

    restored_count = 0
    for tx in session_obj.get('transactions', []):
        if isinstance(tx, dict) and 'tx_id' in tx:
            session_store[tx['tx_id']] = tx
            restored_count += 1

    return jsonify({'restored': restored_count}), 200


@app.route('/api/v2/tx/status/<tx_id>', methods=['GET'])
def get_status(tx_id):
    """Get transaction processing status."""
    if not tx_id or len(tx_id) != 16 or not all(c in '0123456789abcdef' for c in tx_id):
        return jsonify({'error': 'invalid tx_id'}), 400

    if tx_id in session_store:
        return jsonify({'tx_id': tx_id, 'status': 'queued'}), 200
    return jsonify({'error': 'not found'}), 404


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8443, debug=False)
